catalog:
: operation === "leaseCases" ? {
                   operation,
                   recordId: "Optional complete renewal or move-out case reference",
                   workspaceId: "Authorized shared record workspace when paging",
                   pagination: "{cursor:null or previous continuationCursor,numItems:1–20}; continue until isDone",
                   description: "Read original agreement/occupancy, proposed renewal or selected condition evidence, planned dates, accountable member, current packet and administrative human review. Proposed terms are not executed renewal. Condition differences do not prove liability. No legal deadline/notice, deduction, refund, payment, eligibility or contractual commitment is authorized. Missing/stale evidence needs an owned next action; a reviewed packet is not verified business completion.",
                 } : operation === "maintenanceCases" ? {
                   operation,
                   recordId: "Optional complete work-order reference",
                   workspaceId: "Authorized shared record workspace when paging",
                   pagination: "{cursor:null or previous continuationCursor,numItems:1–20}; continue until isDone",
                   description: "Read entered maintenance reports, accountable member, plan/holds, current document evidence and human review records. Physical work, vendor dispatch/acceptance and emergency notifications remain unverified; a reported outcome is not verified business completion.",
                 } : operation === "leases" || operation === "leaseHistory" || operation === "rentLedger" ? {
                   operation,
                   recordId: operation !== "leases" ? "Required complete lease reference" : "Optional complete lease reference",
                   workspaceId: "Authorized organization-owned workspace for a listing page",
                   pagination: "{cursor:null or previous continuationCursor,numItems:1–20}; continue until isDone",
                   description: "Read recorded proposals, human-recorded execution, source freshness and separate occupancy. History preserves original entered versions. rentLedger reads immutable attested entries and their mathematical net, never a complete balance. No rent balance, legal validity, notice, collection or eligibility authority. Report conflicting/unknown evidence.",
                 }

handlers:
if (operation === "leaseCases") {
  if (input.search !== undefined) throw new Error("Case search is not available; read scoped pages")
  return leaseCasePage(ctx, await spacesFor(ctx, scope), input)
}
if (operation === "maintenanceCases") {
  if (input.search !== undefined) throw new Error("Maintenance search is not available; read scoped pages")
  return maintenancePage(ctx, await spacesFor(ctx, scope), input)
}
if (operation === "leases" || operation === "leaseHistory" || operation === "rentLedger") {
  if (input.search !== undefined) throw new Error("Lease search is not available; read scoped pages")
  const allowed = await spacesFor(ctx, scope)
  return operation === "leases" ? rentalContextPage(ctx, allowed, input) : operation === "leaseHistory" ? rentalHistoryPage(ctx, allowed, input) : rentLedgerPage(ctx, allowed, input)
}
